import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.dMg474VA.js";const u=JSON.parse('{"title":"RLGW Observability & Metrics Catalog","description":"","frontmatter":{},"headers":[],"relativePath":"observability.md","filePath":"observability.md"}'),r={name:"observability.md"};function c(i,e,s,l,n,_){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="rlgw-observability-metrics-catalog" tabindex="-1">RLGW Observability &amp; Metrics Catalog <a class="header-anchor" href="#rlgw-observability-metrics-catalog" aria-label="Permalink to &quot;RLGW Observability &amp; Metrics Catalog&quot;">​</a></h1><p>This document details all Prometheus metric series, log schemas, and distributed trace semantics emitted by the RLGW gateway.</p><hr><h2 id="_1-prometheus-metrics-catalog" tabindex="-1">1. Prometheus Metrics Catalog <a class="header-anchor" href="#_1-prometheus-metrics-catalog" aria-label="Permalink to &quot;1. Prometheus Metrics Catalog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric Name</th><th>Type</th><th>Labels</th><th>Description</th></tr></thead><tbody><tr><td><code>rlgw_decisions_total</code></td><td>Counter</td><td><code>tenant</code>, <code>policy_id</code>, <code>decision</code>, <code>reason</code></td><td>Total rate limit decisions evaluated by the gateway (<code>allowed</code> or <code>denied</code>)</td></tr><tr><td><code>rlgw_decision_duration_seconds</code></td><td>Histogram</td><td><code>algorithm</code>, <code>decision</code></td><td>Decision latency in seconds with sub-millisecond exponential buckets</td></tr><tr><td><code>rlgw_dropped_requests_total</code></td><td>Counter</td><td><code>reason</code></td><td>Total requests dropped due to queue overflow, load shedding, or circuit breaking</td></tr><tr><td><code>rlgw_store_operation_duration_seconds</code></td><td>Histogram</td><td><code>backend</code>, <code>operation</code></td><td>Latency of store backend operations (<code>peek</code>, <code>commit</code>, <code>refund</code>, <code>decide</code>)</td></tr><tr><td><code>rlgw_redis_command_duration_seconds</code></td><td>Histogram</td><td><code>command</code>, <code>status</code></td><td>Redis execution duration per command or Lua script (<code>ok</code> vs <code>error</code>)</td></tr><tr><td><code>rlgw_circuit_breaker_state</code></td><td>Gauge</td><td><code>upstream_id</code></td><td>Current circuit breaker state: <code>0</code> (closed), <code>1</code> (half_open), <code>2</code> (open)</td></tr><tr><td><code>rlgw_pipeline_stage_duration_seconds</code></td><td>Histogram</td><td><code>stage</code></td><td>Latency of internal pipeline stages (<code>normalize</code>, <code>identity</code>, <code>policy_match</code>)</td></tr><tr><td><code>rlgw_gateway_info</code></td><td>Gauge</td><td><code>version</code>, <code>node_version</code></td><td>Constant metadata gauge reporting active software release</td></tr><tr><td><code>rlgw_metrics_series_dropped_total</code></td><td>Gauge</td><td>—</td><td>Total cardinality overflow series grouped into fallback <code>other</code> label bucket</td></tr></tbody></table><hr><h2 id="_2-cardinality-protection-strategy" tabindex="-1">2. Cardinality Protection Strategy <a class="header-anchor" href="#_2-cardinality-protection-strategy" aria-label="Permalink to &quot;2. Cardinality Protection Strategy&quot;">​</a></h2><p>To prevent metric cardinality explosions from arbitrary high-cardinality client IDs or spoofed IPs:</p><ol><li>Metric labels only use validated tenant IDs, policy IDs, and standard reason codes.</li><li>Route labels only use template route paths (e.g. <code>/users/:id</code>), never raw URLs with IDs.</li><li>If active series combinations exceed the configured <code>maxSeriesPerFamily</code> budget (default: 1,000), labels are automatically grouped into <code>&#39;other&#39;</code> and <code>rlgw_metrics_series_dropped_total</code> is incremented.</li></ol>',9)])])}const p=t(r,[["render",c]]);export{u as __pageData,p as default};
